  public function executeXml()
  {
  	$doc_id = $this->getRequestParameter('documentacion_id');
  	$documentacion = DocumentacionPeer::retrieveByPK($doc_id);
  	$pfolder_raiz = ParametroPeer::retrieveByPK(48)->getValorTexto();
  	$pfolder_tmp = ParametroPeer::retrieveByPK(65)->getValorTexto();
  	$palias = ParametroPeer::retrieveByPK(67)->getValorTexto();
  	$folder_target = simad_util::createPath($pfolder_raiz.$pfolder_tmp);
  	$stralias = $palias.$pfolder_tmp;
	/***********************************************************************************************************/
	$c = new Criteria();
	$c->addJoin(MarcPeer::MARC_ID,MarcVariableDocPeer::MARC_ID);
	$c->add(MarcVariableDocPeer::DOCUMENTACION_ID,$doc_id);
	$c->addAscendingOrderByColumn(MarcPeer::MARC_ID);
	$codigo_marc_doc = MarcVariableDocPeer::doSelect($c); 
	/***********************************************************************************************************/
		
	/***********************************************************************************************************/
	$xml = new DOMDocument("1.0","UTF-8");	
	$root = $xml->createElement('collection');		
	$xml->appendChild($root);	
	$root->setAttribute('xmlns','http://www.loc.gov/MARC21/slim');
	$root->setAttribute('xmlns:xsi','http://www.w3.org/2001/XMLSchema-instance');
	$root->setAttribute('xsi:schemaLocation','http://www.loc.gov/MARC21/slim http://www.loc.gov/standards/marcxml/schema/MARC21slim.xsd');
	$rec = $xml->createElement('record');
	$root->appendChild($rec);
	/***********************************************************************************************************/
	$leader = $xml->createElement('leader');
	$text = $xml->createTextNode(('00834nw   2200193n  4500'));
	$leader->appendChild($text);
	$rec->appendChild($leader);
	
	
	$campo_control1 = $xml->createElement('controlfield');
	$campo_control1->setAttribute('tag',001);
	$val1  = $xml->createTextNode((sprintf("%05d",$documentacion->getDocumentacionId())));	
	$campo_control1->appendChild($val1);
	$rec->appendChild($campo_control1);
	
	$campo_control2 = $xml->createElement('controlfield');
	$campo_control2->setAttribute('tag',003);
	$val2  = $xml->createTextNode(('ANH'));	
	$campo_control2->appendChild($val2);
	$rec->appendChild($campo_control2);
	
	$campo_control3 = $xml->createElement('controlfield');
	$campo_control3->setAttribute('tag',005);
	$val3  = $xml->createTextNode((date('Ymd Gis')));	
	$campo_control3->appendChild($val3);
	$rec->appendChild($campo_control3);
	
	$campo_control4 = $xml->createElement('controlfield');
	$campo_control4->setAttribute('tag',008);
	$val4  = $xml->createTextNode((date('Ymd Gis').'m'.date('Ymd Gis').'xx#---'.'############vl'.$documentacion->getIdioma()->getCodigo().'#d'));	
	$campo_control4->appendChild($val4);
	$rec->appendChild($campo_control4);
	$temp = '';
	foreach($codigo_marc_doc as $codigo){
		
		if($codigo->getMarc()->getCodigo() != $temp){
			$cod = $xml->createElement('datafield');		
			$cod->setAttribute('tag',$codigo->getMarc()->getCodigo());
			$cod->setAttribute('ind1',$codigo->getMarcindicadorprimario()->getCodigo());
			$cod->setAttribute('ind2',$codigo->getMarcindicadorsecundario()->getCodigo());
		}		
		$sub = $xml->createElement('subfield');
		$sub->setAttribute('code',$codigo->getMarcsubcampo()->getCodigo());
		$text = $xml->createTextNode($codigo->getValorVariable());
		$sub->appendChild($text);
		$cod->appendChild($sub);
				
		$temp = $codigo->getMarc()->getCodigo();
		$rec->appendChild($cod);
				
	}	
	$this->filename = time()."_"."MARCXML.xml";
	$xml->save($folder_target."/".$this->filename);	
	$this->filelink = $stralias ."/".$this->filename;
	
	/***********************************************************************************************************/	  
  }  	
  	 
