  public function executeDelete()
  {
    $documentacion = DocumentacionPeer::retrieveByPk($this->getRequestParameter('documentacion_id'));

    $this->forward404Unless($documentacion);

    $documentacion->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/documentacion_tecnica/list');
  }
  
